-- SifoButchery initial schema proposal. Review before applying to any database.
create extension if not exists pgcrypto;
create table if not exists public.companies(id uuid primary key default gen_random_uuid(),name text not null,currency char(3) not null default 'ZMW',created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,name text not null,created_at timestamptz not null default now(),unique(company_id,name));
create table if not exists public.stock_items(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,sku text not null,name text not null,unit text not null default 'kg',sale_price numeric(14,2) not null default 0 check(sale_price>=0),active boolean not null default true,unique(branch_id,sku));
create table if not exists public.intake_batches(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,batch_no text not null,source text,received_at timestamptz not null default now,gross_weight_kg numeric(14,3) not null check(gross_weight_kg>0),cost_total numeric(14,2) not null default 0 check(cost_total>=0),status text not null default 'received' check(status in('received','graded','cut','closed')),unique(branch_id,batch_no));
create table if not exists public.yield_records(id uuid primary key default gen_random_uuid(),batch_id uuid not null references public.intake_batches(id) on delete cascade,stock_item_id uuid references public.stock_items(id),output_weight_kg numeric(14,3) not null check(output_weight_kg>=0),unit_cost numeric(14,4) not null default 0 check(unit_cost>=0),recorded_at timestamptz not null default now());
create table if not exists public.stock_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id) on delete cascade,branch_id uuid not null references public.branches(id) on delete cascade,stock_item_id uuid not null references public.stock_items(id),movement_type text not null check(movement_type in('intake','sale','wastage','transfer','adjustment')),qty_kg numeric(14,3) not null check(qty_kg<>0),unit_cost numeric(14,4) not null default 0,reference text,created_at timestamptz not null default now());
create table if not exists public.audit_events(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,actor_id uuid,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
